const cfg = $('⚙️ CONFIG').first().json;
const rows = $input.all().map(i => i.json);

const blogs = rows.filter(b =>
  (b.ACTIVE === 'YES' || b.ACTIVE === 'yes') &&
  b.BLOG_ID && String(b.BLOG_ID).length > 5 &&
  !String(b.BLOG_ID).startsWith('ASSET')
);

if (!blogs.length) return [{ json: { _fatalError: 'Sin blogs activos.' } }];

blogs.sort((a, b) => {
  const da = a.CLUSTERS_ULTIMO_PROCESO ? new Date(a.CLUSTERS_ULTIMO_PROCESO) : new Date(0);
  const db = b.CLUSTERS_ULTIMO_PROCESO ? new Date(b.CLUSTERS_ULTIMO_PROCESO) : new Date(0);
  return da - db;
});

const b = blogs[0];
const txt = ((b.NICHO || '') + ' ' + (b.BLOG_NAME || '')).toLowerCase();
const lkw = ['abog','litig','legal','leyes','impuesto','multa','accidente',
              'bienes ra','familia usa','herencia','divorcio','demanda','delito'];
const isLegal = lkw.some(k => txt.includes(k));
const estrategia = b.ESTRATEGIA || (isLegal ? 'lead_abogados' : 'animales_productos');

return [{ json: {
  BLOG_ID:          String(b.BLOG_ID),
  BLOG_NAME:        b.BLOG_NAME,
  NICHO:            b.NICHO,
  ESPECIE:          b.ESPECIE || '',
  AMAZON_TAG:       b.AMAZON_TAG || '',
  ESTRATEGIA:       estrategia,
  IS_LEGAL:         isLegal,
  FUNNEL_URL:       b.LEAD_MAGNET_URL || (isLegal ? cfg.FUNNEL_ABOGADOS : cfg.FUNNEL_ANIMALES),
  PREMIUM_FORM_URL: b.PREMIUM_FORM_URL || cfg.PREMIUM_URL_DEFAULT,
  BRAND_COLOR:      b.BRAND_COLOR || (isLegal ? cfg.COLOR_ABOGADOS : cfg.COLOR_ANIMALES),
  LEAD_STD:         parseFloat(b.LEAD_VALUE_STANDARD) || 150,
  LEAD_PREM:        parseFloat(b.LEAD_VALUE_PREMIUM) || 250,
  PAGE_TOKEN:       b.NEXT_PAGE_TOKEN || '',
  _row:             b._rowNumber,
  DEEPSEEK_KEY:     cfg.DEEPSEEK_API_KEY,
  LABEL_PILAR:      cfg.LABEL_PILAR,
  SHEET_ID:         cfg.SHEET_ID,
  HOJA_BLOGS:       cfg.HOJA_BLOGS,
  MAX_PER_PAGE:     cfg.POSTS_PER_PAGE || 10
}}];

const blogCfg   = $('🎯 Seleccionar Blog (Rotación)').first().json;
const pilarResp = $('🏛️ Obtener Posts Pilar').first().json;
const clustResp = $('📄 Obtener Página de Clusters').first().json;

const LABEL_PILAR    = blogCfg.LABEL_PILAR.toLowerCase();
const nextPageToken  = clustResp.nextPageToken || '';
const clusterPosts   = clustResp.items || [];

// Construir mapa de pilares: { topicLabel → {title, url} }
const pilarMap = {};
for (const p of (pilarResp.items || [])) {
  for (const lbl of (p.labels || [])) {
    if (lbl.toLowerCase() !== LABEL_PILAR) {
      pilarMap[lbl.toLowerCase()] = { title: p.title, url: p.url };
    }
  }
}

// Encontrar el PRIMER cluster post sin procesar
const unprocessed = clusterPosts.filter(post => {
  const labels = (post.labels || []).map(l => l.toLowerCase());
  if (labels.includes(LABEL_PILAR)) return false; // skip pilares
  return !(post.content || '').includes('<!-- EARLY_CTA -->');
});

if (!unprocessed.length) {
  return [{ json: {
    _noPost: true,
    nextPageToken,
    BLOG_ID:    blogCfg.BLOG_ID,
    SHEET_ID:   blogCfg.SHEET_ID,
    HOJA_BLOGS: blogCfg.HOJA_BLOGS,
    _row:       blogCfg._row,
    message:    `Sin posts sin procesar en esta página. Avanzando a siguiente página.`
  }}];
}

const post   = unprocessed[0];
const labels = (post.labels || []).map(l => l.toLowerCase());
const topics = labels.filter(l => l !== LABEL_PILAR);

// Pilar relacionado con este cluster
let pillarTitle = null, pillarUrl = null;
for (const t of topics) {
  if (pilarMap[t]) { pillarTitle = pilarMap[t].title; pillarUrl = pilarMap[t].url; break; }
}

// Clusters hermanos en la misma página
const siblings = clusterPosts
  .filter(p => p.id !== post.id && (p.labels || []).some(l => topics.includes(l.toLowerCase())))
  .slice(0, 3)
  .map(p => ({ title: p.title, url: p.url }));

// ⚖️ LEY 2: detectar qué bloques faltan
const c = post.content || '';
return [{ json: {
  id:    post.id,  title: post.title,
  url:   post.url, labels, content: c,
  pillarTitle, pillarUrl, siblings,
  _noPost: false, nextPageToken,
  needsContextualLinks: !c.includes('<!-- CONTEXTUAL_LINKS -->'),
  needsEarlyCta:        !c.includes('<!-- EARLY_CTA -->'),
  needsCommercial:      !c.includes('<!-- COMMERCIAL_BLOCKS -->'),
  needsSecondCta:       !c.includes('<!-- SECOND_CTA -->'),
  needsPopup:           !c.includes('<!-- POPUP_BLOCK -->'),
  needsFaqSchema:       !c.includes('<!-- FAQ_SCHEMA -->'),
  ...blogCfg
}}];

// ⚖️ LEY 1: DeepSeek NUNCA recibe el HTML del artículo.
// Solo recibe: título, labels, especie, datos de pilar/siblings, URLs, colores.

const p = $input.item.json;
const isLegal = p.IS_LEGAL || p.ESTRATEGIA === 'lead_abogados';
const labels  = p.labels.filter(l => l !== 'pilar' && l !== 'pillar').join(', ') || p.NICHO;
const especie = p.ESPECIE || labels;
const bgLight = isLegal ? '#f0f4ff' : '#f0fff4';
const siblingsText = (p.siblings || []).map(s => `"${s.title}" → ${s.url}`).join('\n');

const sys = `Eres un diseñador HTML/CSS experto en blogs y marketing de conversión (hispanohablante, USA).

⚠️ REGLAS ABSOLUTAS:
1. NUNCA incluyas ni reproduzcas el contenido del artículo. No lo tienes.
2. Responde ÚNICAMENTE con JSON válido. Sin markdown.
3. CSS 100% inline. Sin Bootstrap, jQuery ni librerías externas.
4. Emojis ESPECÍFICOS del nicho/especie (NUNCA ✅❌☑️).
5. Todos los bloques HTML deben tener tamaño máximo: 2KB (popups: 5KB).
6. El JS de popups DEBE usar sessionStorage para no repetirse por sesión.
7. El botón de cierre de los popups: font-size 28px, 40×40px, visible.`;

const siloInstr = p.pillarUrl
  ? `Pilar del cluster: "${p.pillarTitle}" → ${p.pillarUrl}
Clusters hermanos:\n${siblingsText || '(ninguno disponible)'}`
  : `No hay pilar identificado. Usa un enlace genérico a la home del blog.`;

let estratInstr = '';

if (isLegal) {
  estratInstr = `
ESTRATEGIA: Captación de leads para abogados (hispanos en USA)
NICHO LEGAL: ${labels}
Funnel (standard $${p.LEAD_STD}): ${p.FUNNEL_URL}
Formulario premium ($${p.LEAD_PREM}): ${p.PREMIUM_FORM_URL}
Color de marca: ${p.BRAND_COLOR}
Blog: ${p.BLOG_NAME}

${p.needsContextualLinks ? `🔷 contextual_links: 2-3 hiperenlaces tipo silo.
• Cada enlace: <span style="display:inline-block;background:${bgLight};padding:4px 10px;border-radius:20px;border:1px solid ${p.BRAND_COLOR}40;margin:2px;">⚖️ <a href="URL" style="color:${p.BRAND_COLOR};text-decoration:none;font-weight:600;">texto ancla legal</a></span>
• position_percentage: entre 20 y 30 (el primero al pilar, los demás a clusters hermanos)` : '🔷 contextual_links: [] (ya existe)'}

${p.needsEarlyCta ? `🎯 early_cta (al 30%):
• CTA de captación de leads. Fondo: #fff3cd. Padding:20px. Border-radius:14px. Borde 2px solid ${p.BRAND_COLOR}.
• Emoji legal urgente grande + título "¿Tuviste [caso legal]? Consulta GRATIS en 24h"
• Botón grande → ${p.FUNNEL_URL}` : '🎯 early_cta: {html:""} (ya existe)'}

${p.needsCommercial ? `🛒 commercial_blocks: 1 bloque tipo comparison_table o FAQ checklist legal.
• Tabla comparativa: ¿Actuar solo vs. con abogado? o checklist de pasos legales urgentes.
• CSS inline, sin JS, mobile-first, max 1.8KB` : '🛒 commercial_blocks: [] (ya existe)'}

${p.needsSecondCta ? `🔥 second_cta (al 65%):
• Urgencia diferente al primer CTA. Ej: "Cupones de consulta gratuita: quedan 3 disponibles"
• Fondo ${p.BRAND_COLOR}, texto blanco, botón blanco con texto del color de marca
• href → ${p.FUNNEL_URL}` : '🔥 second_cta: {html:""} (ya existe)'}

${p.needsPopup ? `🎭 popups: Objeto con popup_exit y popup_scroll.
• popup_exit: título urgente legal + emoji legal + desc 1-2 líneas + ctaText + ctaUrl: ${p.FUNNEL_URL}
• popup_scroll: título de urgencia máxima ("Última oportunidad") + emoji + desc + ctaText + ctaUrl: ${p.FUNNEL_URL}` : '🎭 popups: {} (ya existe)'}

${p.needsFaqSchema ? `📊 faq_schema: 3-5 preguntas frecuentes MUY específicas del caso legal "${labels}" en USA, con respuestas útiles de 1-3 oraciones.` : '📊 faq_schema: {questions:[]} (ya existe)'}`;
} else {
  estratInstr = `
ESTRATEGIA: SEO clusters + venta afiliados Amazon + infoproductos para ${especie}
NICHO: ${especie} / ${labels}
Funnel/lead magnet: ${p.FUNNEL_URL}
Amazon tag: ${p.AMAZON_TAG}
Color de marca: ${p.BRAND_COLOR}
Blog: ${p.BLOG_NAME}

${p.needsContextualLinks ? `🔷 contextual_links: 2-3 hiperenlaces tipo silo.
• Cada enlace: <span style="display:inline-block;background:${bgLight};padding:4px 10px;border-radius:20px;border:1px solid ${p.BRAND_COLOR}40;margin:2px;">[emoji de ${especie}] <a href="URL" style="color:${p.BRAND_COLOR};text-decoration:none;font-weight:600;">texto ancla</a></span>
• position_percentage: entre 20 y 30 (el primero al pilar, los demás a clusters hermanos)
• Usa emojis ESPECÍFICOS de ${especie}` : '🔷 contextual_links: [] (ya existe)'}

${p.needsEarlyCta ? `🎯 early_cta (al 30%):
• CTA de producto/infoproducto para dueños de ${especie}.
• Fondo suave relacionado al color de marca, padding:20px, borde redondeado
• Emoji grande de ${especie} + texto gancho específico + botón → ${p.FUNNEL_URL}` : '🎯 early_cta: {html:""} (ya existe)'}

${p.needsCommercial ? `🛒 commercial_blocks: 1 tabla comparativa de productos para ${especie} o checklist.
• Ej: comparativa de productos top 3 con pros/cons. Si es adecuado, incluir enlaces de afiliado con tag ${p.AMAZON_TAG}.
• CSS inline, no JS, max 1.8KB` : '🛒 commercial_blocks: [] (ya existe)'}

${p.needsSecondCta ? `🔥 second_cta (al 65%):
• Urgencia diferente: oferta por tiempo limitado, descuento, o bonus exclusivo para ${especie}
• Estilo contrastante al primer CTA. Fondo ${p.BRAND_COLOR}, texto blanco
• Botón → ${p.FUNNEL_URL}` : '🔥 second_cta: {html:""} (ya existe)'}

${p.needsPopup ? `🎭 popups: Objeto con popup_exit y popup_scroll.
• popup_exit: sorpresa/regalo para dueños de ${especie} + emoji + desc + ctaText + ctaUrl: ${p.FUNNEL_URL}
• popup_scroll: oferta especial de tiempo limitado para ${especie} + emoji + desc + ctaText + ctaUrl: ${p.FUNNEL_URL}` : '🎭 popups: {} (ya existe)'}

${p.needsFaqSchema ? `📊 faq_schema: 3-5 preguntas frecuentes muy específicas sobre ${especie} relacionadas al tema "${p.title}", con respuestas útiles.` : '📊 faq_schema: {questions:[]} (ya existe)'}`;
}

const usr = `Genera bloques HTML para este post:

📝 Título: "${p.title}"
🏷️ Temas: ${labels}
🔗 Estructura de silos:
${siloInstr}

${estratInstr}

Responde SOLO este JSON (sin markdown):
{
  "keyword_focus": "palabra clave transaccional objetivo del post",
  "contextual_links": [
    {"html": "<span>...</span>", "position_percentage": 23},
    {"html": "<span>...</span>", "position_percentage": 27}
  ],
  "early_cta": {"html": "<div>...</div>", "position_percentage": 30},
  "commercial_blocks": [{"type": "comparison_table", "html": "<table>...</table>"}],
  "second_cta": {"html": "<div>...</div>", "position_percentage": 65},
  "popups": {
    "popup_exit":   {"title": "...", "description": "...", "ctaText": "...", "ctaUrl": "${p.FUNNEL_URL}", "emoji": "..."},
    "popup_scroll": {"title": "...", "description": "...", "ctaText": "...", "ctaUrl": "${p.FUNNEL_URL}", "emoji": "..."}
  },
  "faq_schema": {"questions": [{"question": "...", "answer": "..."}]}
}`;

return { json: {
  ...p,
  _dsBody: JSON.stringify({
    model: 'deepseek-chat',
    messages: [{ role:'system', content:sys },{ role:'user', content:usr }],
    max_tokens: 3200, temperature: 0.76,
    response_format: { type:'json_object' }
  })
}};

// ⚖️ LEY 1: El contenido original es INTOCABLE. Solo se hacen inserciones con slice().
// ⚖️ LEY 2: Si el marcador ya existe en el contenido → skip ese bloque.

const dsItem   = $input.item.json;
const post     = $('🧠 Prompt Multi-Estrategia').item.json;

// --- Parsear respuesta de DeepSeek ---
let raw = '';
try { raw = dsItem.choices[0].message.content || ''; } catch(e) {}
const cleaned = raw.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim();

let B = {};
try { B = JSON.parse(cleaned); } catch(e) { B = {}; }

// --- Helper: insertar en % del contenido original (slice, nunca replace) ---
function insertAt(content, html, pct, markerStart, markerEnd) {
  if (!html || !html.trim()) return content;
  if (content.includes(markerStart)) return content; // LEY 2
  const target = Math.floor(content.length * (pct / 100));
  // Buscar </p> más cercano ANTES del target
  let at = content.lastIndexOf('</p>', target);
  if (at < 0) at = content.indexOf('</p>', target); // fallback: siguiente </p>
  const pos = at > 0 ? at + 4 : target;
  const block = `\n${markerStart}\n${html}\n${markerEnd}\n`;
  return content.slice(0, pos) + block + content.slice(pos);
}

// --- Construir popup HTML+JS desde los datos (plantilla segura, no generada por IA) ---
function buildPopup(uid, bgColor, funnelUrl, pe, ps) {
  const safe = s => (s || '').replace(/`/g,'').replace(/\/script/gi,'<\/script>');
  const E_title = safe(pe.title   || ''); const E_desc = safe(pe.description || '');
  const E_cta   = safe(pe.ctaText || 'Ver más'); const E_url = pe.ctaUrl || funnelUrl;
  const E_emoji = pe.emoji || '🎯';
  const S_title = safe(ps.title   || ''); const S_desc = safe(ps.description || '');
  const S_cta   = safe(ps.ctaText || 'Ver más'); const S_url = ps.ctaUrl || funnelUrl;
  const S_emoji = ps.emoji || '🔥';
  if (!E_title && !S_title) return '';

  return `<!-- POPUP_BLOCK -->
<div id="${uid}e" style="display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.76);z-index:2147483647;align-items:center;justify-content:center;">
  <div style="background:${bgColor};color:#fff;padding:36px 28px;max-width:460px;width:92%;border-radius:18px;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,0.5);position:relative;">
    <button onclick="document.getElementById('${uid}e').style.display='none'" aria-label="Cerrar" style="position:absolute;top:8px;right:10px;background:rgba(255,255,255,0.2);border:none;color:#fff;font-size:28px;cursor:pointer;width:40px;height:40px;border-radius:50%;">✕</button>
    <div style="font-size:52px;margin:0 0 14px;">${E_emoji}</div>
    <h3 style="margin:0 0 12px;font-size:1.35em;font-weight:800;">${E_title}</h3>
    <p style="margin:0 0 22px;opacity:.9;line-height:1.6;font-size:.97em;">${E_desc}</p>
    <a href="${E_url}" rel="noopener" style="display:inline-block;background:#fff;color:${bgColor};padding:14px 34px;border-radius:50px;font-weight:800;font-size:1.05em;text-decoration:none;">${E_cta}</a>
    <p onclick="document.getElementById('${uid}e').style.display='none'" style="margin:14px 0 0;font-size:.8em;opacity:.5;cursor:pointer;">No gracias</p>
  </div>
</div>
<div id="${uid}s" style="display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.76);z-index:2147483647;align-items:center;justify-content:center;">
  <div style="background:${bgColor};color:#fff;padding:36px 28px;max-width:460px;width:92%;border-radius:18px;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,0.5);position:relative;">
    <button onclick="document.getElementById('${uid}s').style.display='none'" aria-label="Cerrar" style="position:absolute;top:8px;right:10px;background:rgba(255,255,255,0.2);border:none;color:#fff;font-size:28px;cursor:pointer;width:40px;height:40px;border-radius:50%;">✕</button>
    <div style="font-size:52px;margin:0 0 14px;">${S_emoji}</div>
    <h3 style="margin:0 0 12px;font-size:1.35em;font-weight:800;">${S_title}</h3>
    <p style="margin:0 0 22px;opacity:.9;line-height:1.6;font-size:.97em;">${S_desc}</p>
    <a href="${S_url}" rel="noopener" style="display:inline-block;background:#fff;color:${bgColor};padding:14px 34px;border-radius:50px;font-weight:800;font-size:1.05em;text-decoration:none;">${S_cta}</a>
    <p onclick="document.getElementById('${uid}s').style.display='none'" style="margin:14px 0 0;font-size:.8em;opacity:.5;cursor:pointer;">Cerrar</p>
  </div>
</div>
<script>
(function(){
  var u='${uid}';
  function show(id){
    if(sessionStorage.getItem(u+id))return;
    sessionStorage.setItem(u+id,'1');
    var el=document.getElementById(u+id);
    if(el)el.style.display='flex';
  }
  var t0=Date.now();
  document.addEventListener('mouseleave',function(e){if(e.clientY<=0)show('e');});
  window.addEventListener('scroll',function(){
    var d=document.documentElement;
    var pct=d.scrollTop/(d.scrollHeight-d.clientHeight)*100;
    if(pct>=60)show('s');
  },{passive:true});
})();
<\/script>
<!-- /POPUP_BLOCK -->`;
}

// --- Obtener posiciones originales (antes de cualquier inserción) ---
let content   = post.content;
const origLen = content.length;

// --- Preparar todas las inserciones como lista ordenada por posición DESC ---
// (insertar de abajo hacia arriba para no desplazar las posiciones superiores)
const insertions = [];

// 1. Hiperenlaces contextuales tipo silo
if (post.needsContextualLinks && B.contextual_links?.length) {
  for (const link of B.contextual_links) {
    if (link.html && link.position_percentage) {
      insertions.push({
        pct:     link.position_percentage,
        html:    link.html,
        marker:  null // se rastrean con el marcador agregado al final
      });
    }
  }
}

// 2. Early CTA (30%)
if (post.needsEarlyCta && B.early_cta?.html) {
  insertions.push({
    pct:     B.early_cta.position_percentage || 30,
    html:    B.early_cta.html,
    mStart:  '<!-- EARLY_CTA -->',
    mEnd:    '<!-- /EARLY_CTA -->'
  });
}

// 3. Commercial blocks (~50%)
if (post.needsCommercial && B.commercial_blocks?.length) {
  insertions.push({
    pct:    50,
    html:   B.commercial_blocks.map(b => b.html).join('\n'),
    mStart: '<!-- COMMERCIAL_BLOCKS -->',
    mEnd:   '<!-- /COMMERCIAL_BLOCKS -->'
  });
}

// 4. Second CTA (65%)
if (post.needsSecondCta && B.second_cta?.html) {
  insertions.push({
    pct:    B.second_cta.position_percentage || 65,
    html:   B.second_cta.html,
    mStart: '<!-- SECOND_CTA -->',
    mEnd:   '<!-- /SECOND_CTA -->'
  });
}

// Ordenar de MAYOR a MENOR posición para no desplazar inserciones previas
insertions.sort((a, b) => b.pct - a.pct);

// Aplicar inserciones de bloque (con marcadores y Ley 2)
for (const ins of insertions) {
  if (!ins.html || !ins.html.trim()) continue;
  if (ins.mStart && content.includes(ins.mStart)) continue; // LEY 2
  const target = Math.floor(origLen * (ins.pct / 100));
  let at = content.lastIndexOf('</p>', target);
  if (at < 0) at = content.indexOf('</p>', target);
  const pos = at > 0 ? at + 4 : target;
  const block = ins.mStart
    ? `\n${ins.mStart}\n${ins.html}\n${ins.mEnd}\n`
    : `\n${ins.html}\n`;
  content = content.slice(0, pos) + block + content.slice(pos);
}

// Si se insertaron contextual_links, agregar marcador rastreador al final
if (post.needsContextualLinks && B.contextual_links?.length && !content.includes('<!-- CONTEXTUAL_LINKS -->')) {
  content += '\n<!-- CONTEXTUAL_LINKS --><!-- /CONTEXTUAL_LINKS -->';
}

// 5. FAQ Schema (JSON-LD) — al final
if (post.needsFaqSchema && B.faq_schema?.questions?.length > 0 && !content.includes('<!-- FAQ_SCHEMA -->')) {
  const ld = JSON.stringify({
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: B.faq_schema.questions.map(q => ({
      '@type': 'Question',
      name: q.question,
      acceptedAnswer: { '@type': 'Answer', text: q.answer }
    }))
  });
  content += `\n<!-- FAQ_SCHEMA -->\n<script type="application/ld+json">${ld}</scr` + `ipt>\n<!-- /FAQ_SCHEMA -->`;
}

// 6. Popups (HTML+JS con template seguro) — al final
const popData = B.popups || {};
if (post.needsPopup && !content.includes('<!-- POPUP_BLOCK -->')) {
  const uid = 'p' + String(post.id).slice(-8);
  const popHtml = buildPopup(uid, post.BRAND_COLOR, post.FUNNEL_URL,
    popData.popup_exit  || {},
    popData.popup_scroll || {}
  );
  if (popHtml) content += '\n' + popHtml;
}

const changed = content !== post.content;

return { json: {
  id:         post.id,
  title:      post.title,
  BLOG_ID:    post.BLOG_ID,
  newContent: content,
  _changed:   changed,
  _skipped:   !changed,
  kwFocus:    B.keyword_focus || '',
  nextPageToken:  post.nextPageToken,
  _row:           post._row,
  SHEET_ID:       post.SHEET_ID,
  HOJA_BLOGS:     post.HOJA_BLOGS,
  BLOG_ID_SHEET:  post.BLOG_ID
}};

const b = $('🎯 Seleccionar Blog (Rotación)').first().json;
const p = $('🔍 Seleccionar 1 Post Sin Procesar').first().json;
return [{ json: {
  status:     '✅ Post procesado',
  blog:        b.BLOG_NAME,
  estrategia:  b.ESTRATEGIA,
  post:        p.title,
  kwFocus:     $('💉 Inyección Multi-Bloque (Ley 1+2)').first().json.kwFocus || '',
  timestamp:   new Date().toLocaleString('es-MX'),
